mapper.select:
SELECT pr.DATA_STATUS dataStatus, pr.REVIEW_YESNO reviewYesno, pr.REQUIREMENT_USER requirementUser, pra.REPORT_STATUS reportStatus, pr.REQUIREMENT_ID requirementId, pr.REQUIREMENT_BASIS requirementBasis, pr.REQUIREMENT_DATE requirementTime, pr.TAR_CUSTOMER tarCustomer, pr.PRD_SCALE prdScale, pr.PRD_PERIOD prdPeriod, pr.PRD_RATE prdRate, pr.PRD_REQUIREMENT_DETIAL prdRequirementDetail, pr.REQUIREMENT_SOURCE requirementSource FROM PRODUCT_REQUIREMENT pr LEFT JOIN PRODUCT_REQUIREMENT_ADD pra ON pr.REQUIREMENT_ID = pra.REQUIREMENT_ID WHERE 1 = 1
AND pr.DATA_STATUS = #{dataStatus}
AND pr.REQUIREMENT_SOURCE = #{requirementSource}
and pr.REQUIREMENT_DATE >= STR_TO_DATE(#{requirementTimeStart}, '%Y-%m-%d')
and pr.REQUIREMENT_DATE <= STR_TO_DATE(#{requirementTimeEnd}, '%Y-%m-%d')
AND pr.TAR_CUSTOMER like concat(concat('%',#{tarCustomer}),'%')
AND pra.REPORT_STATUS = #{reportStatus}
